/**
 * Star precomp — generated by `remotion-ui import-ae` from star-splosion.json (Bodymovin 5.7.1).
 * 512×512 at 60 fps, 60 frames.
 *
 * Plain data on top of `ae-motion`: keyframe frames are this composition's
 * frames, speed is units per second, scale is a factor and opacity is 0–1.
 * Edit a key, a colour or a layer's inPoint/outPoint/startTime and re-render.
 */
import { AeLayer, shapeLayer, star, fill, stroke } from "@/remotion/lib/ae-import";

/** "Shape Layer" — shape layer, frames 0–60. */
const shapeLayerLayer = shapeLayer({
  name: "Shape Layer",
  inPoint: 0,
  outPoint: 60,
  contents: [
    star({
      position: [
        { frame: 0, value: [256, 256], interpolation: "linear" },
        { frame: 60, value: [0, 0] },
      ],
      points: 5,
      outerRadius: [
        { frame: 0, value: 0, interpolation: "linear" },
        { frame: 30, value: 80, interpolation: "linear" },
        { frame: 51, value: 80, interpolation: "linear" },
        { frame: 60, value: 0 },
      ],
      innerRadius: [
        { frame: 0, value: 0, interpolation: "linear" },
        { frame: 30, value: 40, interpolation: "linear" },
        { frame: 51, value: 40, interpolation: "linear" },
        { frame: 60, value: 0 },
      ],
      rotation: -45,
    }),
    stroke({ color: "#ff5704", width: 6 }),
    fill({ color: "#fffa48" }),
  ],
});

export const ShapeLayer = () => <AeLayer layer={shapeLayerLayer} />;

/** "Star" precomp (512×512), bottom layer first. */
export const StarPrecomp = () => (
  <>
    <ShapeLayer />
  </>
);
